"""Wait without Torch; measure generated bytes only after the existing GPU queue exits."""
import argparse
import fcntl
import json
import os
from pathlib import Path
import select
import subprocess
import sys
import time

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from audit import free_guard_native_contract as contract
from audit.surface_device_queue import check_owner, identity, need, sha, write


def execute(label, script, args, output, fd, *, worker_owner):
    contract.owner_fd(fd)
    command = [sys.executable, '-I', str(contract.REPO / 'scripts' / script), *args, '--output', str(output)]
    if worker_owner:
        command += ['--owner-fd', str(fd)]
    env = dict(os.environ, OMP_NUM_THREADS='1', MKL_NUM_THREADS='1', OPENBLAS_NUM_THREADS='1')
    need(env.get('CUDA_VISIBLE_DEVICES') != '', 'FREE_GUARD_GPU_HIDDEN')
    with output.with_suffix('.log').open('xb') as log:
        child = subprocess.Popen(command, stdout=log, stderr=subprocess.STDOUT, env=env, pass_fds=(fd,))
        write(output.with_suffix('.launch.json'), dict(pid=child.pid, starttime=identity(child.pid), command=command))
        status = child.wait(); log.flush(); os.fsync(log.fileno())
    need(status == 0, 'FREE_GUARD_CHILD_FAILED:' + label)
    path = output / 'report.json'; pin = sha(path)
    need(contract.read(path, pin)['complete'], 'FREE_GUARD_CHILD_INCOMPLETE')
    return dict(label=label, path=str(path), pin=pin)


def run(a):
    cfg, _, fresh = contract.authenticate(a.authority, a.pin)
    proof = contract.read(a.proof / 'report.json', a.proof_pin)
    need(proof['complete'] and proof['authority'] == a.pin and proof['code'] == cfg['code']
         and proof['real_plan_readback'] and proof['owner_controls_passed'] and proof['no_gpu_started'], 'FREE_GUARD_QUEUE_PROOF')
    with contract.LOCK.open('a+b') as owner:
        fcntl.flock(owner, fcntl.LOCK_EX | fcntl.LOCK_NB); a.output.mkdir(exist_ok=False)
        write(a.output / 'launch.json', dict(pid=os.getpid(), starttime=identity(os.getpid()), authority=a.pin,
            driver_pin=sha(__file__), proof=a.proof_pin, wait=cfg['wait']))
        def event(stage, **values):
            with (a.output / 'events.jsonl').open('a') as stream:
                stream.write(json.dumps(dict(stage=stage, time=time.time(), **values), sort_keys=True) + '\n')
                stream.flush(); os.fsync(stream.fileno())
        wait = cfg['wait']; fresh(); check_owner(wait)
        if identity(wait['pid']) == wait['starttime']:
            try:
                fd = os.pidfd_open(wait['pid'])
            except ProcessLookupError:
                pass
            else:
                try:
                    check_owner(wait); need('torch' not in sys.modules, 'FREE_GUARD_EARLY_TORCH')
                    event('waiting', owner=wait, method='kernel_pidfd', torch_loaded=False); select.select([fd], [], [])
                finally:
                    os.close(fd)
        began = tick = time.perf_counter(); fresh(); predecessor = contract.predecessor(cfg)
        write(a.output / 'handoff.json', dict(predecessor=predecessor, plan=cfg['plan']))
        phases = dict(handoff=time.perf_counter() - tick); outputs = []; args = ['--plan', cfg['plan']['path'], '--pin', cfg['plan']['pin']]
        for label in contract.STAGES:
            fresh(); tick = time.perf_counter(); event('launching', label=label)
            if label in ('measure', 'cold'):
                extra = [] if label == 'measure' else ['--reference', str(a.output / 'measure'), '--reference-pin', outputs[0]['pin']]
                ref = execute(label, 'text/free_guard_native_measure.py', args + extra, a.output / label, owner.fileno(), worker_owner=True)
            else:
                extra = ['--input', str(a.output / 'measure'), '--input-pin', outputs[0]['pin'],
                    '--cold', str(a.output / 'cold'), '--cold-pin', outputs[1]['pin']]
                ref = execute(label, 'audit/free_guard_native_readback.py', args + extra, a.output / label, owner.fileno(), worker_owner=False)
            contract.result_check(label, contract.read(ref['path'], ref['pin']), cfg, outputs); outputs.append(ref)
            phases[label] = time.perf_counter() - tick; event('completed', **ref)
        fresh(); seconds = time.perf_counter() - began
        need(.9 <= sum(phases.values()) / seconds <= 1.001, 'FREE_GUARD_QUEUE_PHASES')
        write(a.output / 'report.json', dict(complete=True, authority=a.pin, proof=a.proof_pin, driver_pin=sha(__file__),
            predecessor=predecessor, outputs=outputs, policy=contract.POLICY, capability_demonstrated=False,
            semantic_validity_established=False, phases=phases, seconds_after_wait=seconds, acceptance='author-checked'))
        event('terminal', pin=sha(a.output / 'report.json'))


if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__); p.add_argument('--prepare', action='store_true')
    for name in ('authority', 'proof', 'output', 'plan'):
        p.add_argument('--' + name, type=Path)
    p.add_argument('--pin'); p.add_argument('--proof-pin'); p.add_argument('--plan-pin'); a = p.parse_args()
    try:
        if a.prepare:
            print(json.dumps(dict(pin=contract.prepare(dict(path=str(a.plan), pin=a.plan_pin), a.output))), flush=True)
        else:
            run(a)
    except BaseException as exc:
        if a.output is not None and a.output.exists():
            write(a.output / 'failure.json', dict(error=repr(exc)))
        raise
